<?php
if($action==='publish'){
    $u=require_api_mutation_auth($pdo);rate_limit_api($pdo,$config,'publish_user',rate_limit_subject_user($u),20,300);rate_limit_api($pdo,$config,'publish_user_day',rate_limit_subject_user($u),100,86400);$url=trim((string)($input['url']??''));$selected=trim((string)($input['selected_text']??''));$comment=trim((string)($input['commentary']??''));$type=(string)($input['capture_type']??'text');$start=isset($input['start_seconds'])?(float)$input['start_seconds']:null;$end=isset($input['end_seconds'])?(float)$input['end_seconds']:null;
    if(!filter_var($url,FILTER_VALIDATE_URL))json_response(['ok'=>false,'error'=>['code'=>'INVALID_URL']],422);
    if(!in_array($type,['text','video_clip','audio_clip','image_region','page_region'],true))json_response(['ok'=>false,'error'=>['code'=>'INVALID_CAPTURE_TYPE']],422);
    if(in_array($type,['video_clip','audio_clip'],true)&&($start===null||$end===null||$end<=$start||($end-$start)>90))json_response(['ok'=>false,'error'=>['code'=>'CLIP_TOO_LONG','message'=>'Clips must be 90 seconds or less.']],422);
    if($selected===''&&$comment===''&&empty($input['audio_commentary'])&&!in_array($type,['video_clip','audio_clip','image_region','page_region'],true))json_response(['ok'=>false,'error'=>['code'=>'EMPTY_ANNOTATION']],422);
    try{$contextPath=save_data_url_image((string)($input['screenshot_context']??''),'context',$config);$targetPath=save_data_url_image((string)($input['screenshot_target']??''),'target',$config);$audioPath=save_data_url_audio((string)($input['audio_commentary']??''),$config);}catch(Throwable $e){json_response(['ok'=>false,'error'=>['code'=>'CAPTURE_INVALID','message'=>$e->getMessage()]],422);}
    $canonical=canonicalize_url($url);$pageText=(string)($input['page_text']??'');$pageHash=hash('sha256',$pageText);$targetHash=hash('sha256',$selected);
    $pdo->beginTransaction();
    try{
        $source=ensure_source($pdo,$canonical,$input['title']??null,$input['media_type']??null);$sourceId=(int)$source['id'];$source=lock_source_row($pdo,$sourceId);$previousVersionId=(int)($source['current_version_id']??0);$versionId=$previousVersionId;$current=source_current_version($pdo,$source);$currentHash=$current['content_hash']??null;
        if(!$versionId||($pageText!==''&&$currentHash!==$pageHash)){
            $next=next_source_version_number($pdo,$sourceId);
            $q=$pdo->prepare('INSERT INTO source_versions(source_id,version_number,final_url,title,extracted_text,content_hash,target_content_hash,screenshot_path,metadata_json) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute([$sourceId,$next,$canonical,$input['title']??null,$pageText?:null,$pageHash,$targetHash,$contextPath,json_encode(['media_type'=>$input['media_type']??null])]);$versionId=(int)$pdo->lastInsertId();
            $targetChanged=false;
            if($previousVersionId&&$pageText!==''){$q=$pdo->prepare('SELECT DISTINCT c.selected_text FROM annotations a JOIN captures c ON c.id=a.capture_id WHERE a.source_id=? AND a.source_version_id=? AND c.selected_text IS NOT NULL AND c.selected_text<>"" LIMIT 100');$q->execute([$sourceId,$previousVersionId]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $priorText){if(!str_contains(normalize_match_text($pageText),normalize_match_text((string)$priorText))){$targetChanged=true;break;}}}
            $status=$previousVersionId?($targetChanged?'edited':'updated'):'current';$pdo->prepare('UPDATE sources SET current_version_id=?,title=COALESCE(?,title),status=? WHERE id=?')->execute([$versionId,$input['title']??null,$status,$sourceId]);
            if($previousVersionId){$pdo->prepare('INSERT INTO source_change_events(source_id,previous_version_id,new_version_id,change_type,target_changed,diff_summary) VALUES(?,?,?,?,?,?)')->execute([$sourceId,$previousVersionId,$versionId,$targetChanged?'edited':'updated',$targetChanged?1:0,$targetChanged?'One or more previously annotated passages no longer match the current source.':'Source content changed; existing annotated passages were still found.']);$q=$pdo->prepare('SELECT DISTINCT user_id FROM annotations WHERE source_id=? AND source_version_id=?');$q->execute([$sourceId,$previousVersionId]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $notifyId)notify_user($pdo,(int)$notifyId,null,'source_changed','source',$source['public_id'],$targetChanged?'A source you annotated changed in a referenced passage.':'A source you annotated was updated.');$q=$pdo->prepare('SELECT user_id FROM source_watches WHERE source_id=?');$q->execute([$sourceId]);foreach($q->fetchAll(PDO::FETCH_COLUMN) as $notifyId)notify_user($pdo,(int)$notifyId,null,'source_changed','source',$source['public_id'],$targetChanged?'A watched source changed in annotated content.':'A watched source was updated.');}
        }
        $q=$pdo->prepare('INSERT INTO captures(public_id,source_id,source_version_id,user_id,capture_type,selected_text,start_seconds,end_seconds,screenshot_target_path,screenshot_context_path,selector_json) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$q->execute([ulid_like(),$sourceId,$versionId,$u['id'],$type,$selected?:null,$start,$end,$targetPath,$contextPath,json_encode($input['selector']??null)]);$captureId=(int)$pdo->lastInsertId();
        $visibility=(string)($input['visibility']??'public');$teamId=null;if($visibility==='team'){$teamId=ext_team_id($pdo,(string)($input['team_id']??''),(int)$u['id']);if(!$teamId)throw new RuntimeException('Invalid team visibility.');}elseif(!in_array($visibility,['public','private'],true))$visibility='public';
        $publicId=ulid_like();$pdo->prepare('INSERT INTO annotations(public_id,user_id,source_id,source_version_id,capture_id,text_commentary,audio_commentary_path,visibility,team_id,status) VALUES(?,?,?,?,?,?,?,?,?,"published")')->execute([$publicId,$u['id'],$sourceId,$versionId,$captureId,$comment?:null,$audioPath,$visibility,$teamId]);$annotationId=(int)$pdo->lastInsertId();
        $transcriptionQueued=false;if($audioPath){$pdo->prepare('INSERT INTO annotation_transcripts(annotation_id,status) VALUES(?,"queued")')->execute([$annotationId]);$transcriptId=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO transcription_jobs(transcript_id,input_path) VALUES(?,?)')->execute([$transcriptId,$audioPath]);$transcriptionQueued=true;}
        if(in_array($type,['video_clip','audio_clip'],true)){$duration=$end-$start;$pdo->prepare('INSERT INTO media_derivatives(capture_id,media_type,duration_seconds,resolution_label,processing_status) VALUES(?,?,?,?,"queued")')->execute([$captureId,$type==='video_clip'?'video':'audio',$duration,$type==='video_clip'?'240p':null]);$derivative=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO media_jobs(derivative_id,source_url,start_seconds,end_seconds) VALUES(?,?,?,?)')->execute([$derivative,$canonical,$start,$end]);}
        $pdo->commit();json_response(['ok'=>true,'data'=>['annotation_id'=>$publicId,'url'=>'/annotation.php?id='.$publicId,'media_queued'=>in_array($type,['video_clip','audio_clip'],true),'transcription_queued'=>$transcriptionQueued]],201);
    }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();json_response(['ok'=>false,'error'=>['code'=>'PUBLISH_FAILED','message'=>$e->getMessage()?:'Unable to publish annotation.']],500);}
}


if($action==='transcript_edit'){
    $u=require_api_mutation_auth($pdo);rate_limit_api($pdo,$config,'transcript_edit_user',rate_limit_subject_user($u),30,600);$a=ext_annotation($pdo,(string)($input['annotation_id']??''));if(!$a||((int)$a['user_id']!==(int)$u['id']&&$u['role']!=='admin'))json_response(['ok'=>false,'error'=>['code'=>'FORBIDDEN']],403);
    $text=trim((string)($input['text']??''));if(mb_strlen($text)>50000)json_response(['ok'=>false,'error'=>['code'=>'TRANSCRIPT_TOO_LONG']],422);
    $q=$pdo->prepare('UPDATE annotation_transcripts SET edited_text=?,updated_at=NOW() WHERE annotation_id=?');$q->execute([$text?:null,$a['id']]);json_response(['ok'=>true,'data'=>['updated'=>true]]);
}
